#[test]
fn fast_path_matches_json_path() {
    // The template-value fast path must produce exactly what the JSON path
    // produces (docs/PERF.md P-005); fixtures cover nested and flat payloads.
    let dir = fixtures().display().to_string();
    let fast = ok(&["parse", "-q", &dir]);
    let slow = ok(&["parse", "-q", "--slow-decoder", &dir]);
    assert_eq!(fast.lines().count(), slow.lines().count());
    for (a, b) in fast.lines().zip(slow.lines()) {
        assert_eq!(a, b);
    }
    let fast = ok(&["parse", "-q", "-F", "csv", &dir]);
    let slow = ok(&["parse", "-q", "-F", "csv", "--slow-decoder", &dir]);
    assert_eq!(fast, slow);
}

#[test]
fn checklist_sweep() {
    let checks = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../skill/references/checklists/checklists.json");
    let checks = checks.display().to_string();
    let out = ok(&[
        "checklist",
        "-q",
        "-k",
        &checks,
        &fx("Security.evtx"),
        &fx("System.evtx"),
        "-F",
        "json",
    ]);
    let v: Value = serde_json::from_str(&out).unwrap();
    let rows = v.as_array().unwrap();
    assert!(rows.len() > 200);
    let status = |id: &str| {
        rows.iter().find(|r| r["id"] == id).unwrap()["status"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert_eq!(status("FH-DEF-001"), "HIT?"); // 1102 in the scenario
    assert_eq!(status("FH-LAT-001"), "HIT?"); // PSEXESVC
    // No Sysmon file given: Sysmon checks must say the source is missing.
    assert_eq!(status("FH-CRED-001"), "LOG_SOURCE_MISSING");
    let md = ok(&[
        "checklist",
        "-q",
        "-k",
        &checks,
        &fx("Security.evtx"),
        "--tactic",
        "impact",
    ]);
    assert!(md.contains("## impact") && !md.contains("## execution"));
}

#[test]
fn cyclic_string_table_does_not_hang() {
    // Header + first chunk of a fixture, with two string-table entries
    // pointing at each other (A -> B -> A).
    let data = std::fs::read(fx("Security.evtx")).unwrap();
    let mut d = data[..4096 + 65536].to_vec();
    let c = 4096;
    let heads: Vec<usize> = (0..64)
        .map(|i| u32::from_le_bytes(d[c + 128 + i * 4..c + 132 + i * 4].try_into().unwrap()))
        .filter(|&o| o != 0)
        .map(|o| o as usize)
        .collect();
    assert!(heads.len() >= 2);
    let (a, b) = (heads[0], heads[1]);
    d[c + a..c + a + 4].copy_from_slice(&(b as u32).to_le_bytes());
    d[c + b..c + b + 4].copy_from_slice(&(a as u32).to_le_bytes());
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("cycle.evtx");
    std::fs::write(&p, &d).unwrap();
    let mut child = Command::new(env!("CARGO_BIN_EXE_forhunt"))
        .args(["stats", "-q", "--slow-decoder", p.to_str().unwrap()])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    for _ in 0..200 {
        if let Some(st) = child.try_wait().unwrap() {
            assert!(st.success(), "{st:?}");
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    child.kill().ok();
    panic!("forhunt hung on a cyclic string table");
}

#[test]
fn sampled_key_collision_keeps_both_files() {
    // corrupt.evtx has the same size and intact ends as Security.evtx, so the
    // sampled keys collide; it must still be parsed (and fail --strict).
    let (sec, bad) = (fx("Security.evtx"), fx("corrupt.evtx"));
    let o = forhunt(&["stats", "--strict", "-q", &sec, &bad]);
    assert_eq!(o.status.code(), Some(4));
    let out = ok(&["search", "-q", &sec, &bad, "-F", "jsonl"]);
    let v = lines(&out);
    let id = v
        .iter()
        .find(|e| {
            e["source_file"]
                .as_str()
                .unwrap_or("")
                .ends_with("corrupt.evtx")
        })
        .unwrap()["id"]
        .as_str()
        .unwrap()
        .to_string();
    assert!(!id.starts_with("4a2aa2ed"), "{id}");
    // Resolvable with or without the colliding file among the inputs.
    for p in [&bad, &fixtures().display().to_string()] {
        let s = lines(&ok(&["show", &id, "-p", p, "-F", "llm"]));
        assert_eq!(s[0]["id"], id.as_str());
    }
}
